select department.tenant_id, department.revision, department.created_by, department.created_time, department.updated_by, department.updated_time, department.deleted_flag, department.deleted_by, department.deleted_time, department.id, department.remark, department.dept_code, department.dept_name, department.order_num, department.leader_id, department.status ,user1.nick_name as leader_name, department.organization_id,department.syn_flag,department.syn_id from system_department as department left join system_user_base as user1 on department.leader_id = user1.id
department.deleted_flag = 'N' and department.status = 1 and department.id in
#{deptId}

select
department.deleted_flag,
department.id, department.remark, department.dept_code, department.dept_name, department.order_num, department.leader_id, department.status ,user1.nick_name as leader_name,
department.organization_id,department.syn_flag,department.syn_id,deptRelation.parent_id
from system_department as department
left join system_user_base as user1 on department.leader_id = user1.id

left join  system_dept_relation as deptRelation on department.id = deptRelation.dept_id and deptRelation.level = 1 and deptRelation.deleted_flag = 'N'

    department.deleted_flag = 'N'
